/// 只读借用字符串视图 (指向调用方内存, UTF-8, 不要求 NUL 结尾)
final class MusicxxExternPluginStringView extends ffi.Struct {
  external ffi.Pointer<ffi.Char> data;

  @ffi.Uint64()
  external int size;
}

/// 插件框架堆分配字符串 (显式所有权: 由插件框架分配, 调用方用 string_free 释放)
final class MusicxxExternPluginString extends ffi.Struct {
  /// < 以 \0 结尾; 空串或未设置时为 NULL
  external ffi.Pointer<ffi.Char> data;

  /// < 字节数 (不含结尾 \0)
  @ffi.Uint64()
  external int size;
}

final class MusicxxExternPluginHost extends ffi.Opaque {}

final class MusicxxExternPluginHostConfig extends ffi.Struct {
  /// < == sizeof(MusicxxExternPluginHostConfig)
  @ffi.Uint32()
  external int struct_size;

  /// < 应用版本 (如 "0.87.0")
  external MusicxxExternPluginStringView app_version;

  /// < 平台标识 (windows/linux/macos/android/ios/ohos)
  external MusicxxExternPluginStringView platform;

  /// < 语言代码 (如 "zh-cn")
  external MusicxxExternPluginStringView language;

  /// < 用户插件目录 (绝对路径; 可为空)
  external MusicxxExternPluginStringView user_plugin_dir;

  /// < 随包插件目录 (绝对路径; 可为空)
  external MusicxxExternPluginStringView builtin_plugin_dir;

  /// < 插件私有数据根目录 (绝对路径; 可为空)
  external MusicxxExternPluginStringView data_dir;

  /// < 日志目录 (绝对路径; 可为空)
  external MusicxxExternPluginStringView log_dir;

  /// 客户端界面能力段 (JSON 文本; 可为空)
  ///
  /// 内容由界面描述层库生成 (支持的组件 / 控件 / 图标 / 上限等), 插件框架只做转发:
  /// `host.info().ui` 与 JS 侧 `musicxx.host.info().ui` 返回同一份,
  /// 插件据此决定该给什么界面内容 (取页面时也会带一份, 见各客户端的取数参数)。
  external MusicxxExternPluginStringView ui_capabilities;

  /// < 0 trace .. 4 error
  @ffi.Int32()
  external int log_level;

  /// < MUSICXX_EXTERN_PLUGIN_FLAG_*
  @ffi.Int32()
  external int flags;

  /// < 0 = 默认 16384
  @ffi.Uint32()
  external int event_queue_capacity;
}

